        if parent[i] == -1:
            return i
        return find(parent, parent[i])

    def union(parent: List[int], x: int, y: int):
        rootX = find(parent, x)
        rootY = find(parent, y)
        if rootX != rootY:
            parent[rootY] = rootX

    parent = [-1] * n
    for u, v in edges:
        union(parent, u, v)

    components = sum(1 for i in range(n) if parent[i] == -1)
    return components
