def solve(n, edges):
    from collections import defaultdict

    def find(x, root):
        if root[x] < 0:
            return x
        root[x] = find(root[x], root)
        return root[x]

    def union(x, y, root):
        x, y = find(x, root), find(y, root)
        if x == y:
            return False
        if root[x] > root[y]:
            x, y = y, x
        root[x] += root[y]
        root[y] = x
        return True

    root = [-1] * n
    for u, v in edges:
        union(u, v, root)

    return sum(1 for x in root if x < 0)
