    nums_with_index.sort()
    i, j = 0, len(nums) - 1
    while i < j:
        current_sum = nums_with_index[i][0] + nums_with_index[j][0]
        if current_sum < target:
            i += 1
        elif current_sum > target:
            j -= 1
        else:
            return [nums_with_index[i][1], nums_with_index[j][1]]
    return []
```

