from math import gcd

def solve(nums):
    n = len(nums) - 1
   积 = 1
    for i in range(1, n + 1):
        积 *= i
    acc = 0
    for num in nums:
        acc += num * 积
    for i in range(1, n + 1):
        acc //= gcd(积 // i, acc // (i * 积 // i))
    return acc // 积

class Solution:
    def solve(self, nums):
        slow = nums[0]
        fast = nums[nums[0]]
        while slow != fast:
            slow = nums[slow]
            fast = nums[nums[fast]]

        slow = 0
        while slow != fast:
            slow = nums[slow]
            fast = nums[fast]

        return slow

class DuplicateFinder:
    def solve(self, nums):
        floor = 1
        ceiling = len(nums) - 1

        while floor < ceiling:
            mid = floor + (ceiling - floor) // 2
            low, high = floor, mid
            count = 0
            for num in nums:
                if low <= num <= high:
                    count += 1
            if count > high - low + 1:
                floor = low
            else:
                ceiling = high

        return floor

